import { ITranslationVersions, Locale } from '../types';

// Base minimum translation versions that all locales inherit
// 0 means no minimum requirement - locales opt-in to specific versions they need
const BASE_MINIMUM_VERSIONS: Omit<ITranslationVersions, 'game'> = {
    shared: 0,
    errors: 0,
    chatRules: 0,
    session: 0
};

// Minimum translation versions required by arcade-base package per locale
// Note: 'game' is not included as games control their own translation versions
export const MINIMUM_TRANSLATION_VERSIONS: Record<Locale, Omit<ITranslationVersions, 'game'>> = {
    'en-gb': {
        ...BASE_MINIMUM_VERSIONS,
        shared: 2,
        errors: 1,
        chatRules: 1
    },
    'it-it': {
        ...BASE_MINIMUM_VERSIONS,
        errors: 1,
        chatRules: 1
    },
    'es-es': {
        ...BASE_MINIMUM_VERSIONS,
        shared: 2,
        errors: 1,
        session: 2
    },
    'dk-dk': {
        ...BASE_MINIMUM_VERSIONS
    },
    'se-se': {
        ...BASE_MINIMUM_VERSIONS,
        shared: 1
    }
};
